5	import TruncatedText from '../TruncatedText'
6	import DriveFolderPickerModal from './components/DriveFolderPickerModal'
7	import DriveThumbnailPanel from './components/ThumbnailPanel'
8	import GroupNode from './components/GroupNode'
9	import FileList from './components/FileList'
10	import ResizableLeftPanel from './components/ResizableLeftPanel'
11	import UploadModal from './components/UploadModal'
12	import { useFileTree } from './hooks/useFileTree'
13	import { useDriveAssignments } from './hooks/useDriveAssignments'
14	import { useInclusion } from './hooks/useInclusion'
15	import { useSelection } from './hooks/useSelection'
16	import { useUploadFlow } from './hooks/useUploadFlow'
17	import { pruneSelectionForAssignment } from './pruneSelection'
18	import { LocalFile, DriveAssignment, SelectionItem } from './types'
19	import * as pageCache from '../../lib/pageCache'
20	import { ellipsisPath } from '../../utils'
21	import styles from './index.module.css'
22	
23	export default function DriveUploadMode() {
24	  const { root, tree, loading, error, pickRoot } = useFileTree()
25	  const isEmpty = tree !== null && tree.files.length === 0 && tree.subgroups.length === 0
26	
27	  // The last previewable file touched by a click — independent of the
28	  // multi-selection (see useSelection): any click on a previewable file
29	  // updates this, whether it's adding or removing that file from the
30	  // selection, while clicking a subfolder or a non-previewable file leaves
31	  // it as whatever was last previewed.
32	  const [previewedFile, setPreviewedFile] = useState<LocalFile | null>(null)
33	  const [previewedPage, setPreviewedPage] = useState(1)
34	  const handlePreviewFile = (file: LocalFile) => {
35	    setPreviewedFile(file)
36	    setPreviewedPage(1)
37	  }
38	
39	  useEffect(() => {
40	    return () => { if (previewedFile) pageCache.evict(previewedFile.path) }
41	    // eslint-disable-next-line react-hooks/exhaustive-deps
42	  }, [previewedFile?.path])
43	
44	  // Groups start expanded; presence in this set (keyed by the group's full
45	  // path, e.g. "invoices/2026") means collapsed.
46	  const [collapsedGroups, setCollapsedGroups] = useState<Set<string>>(new Set())
47	  const toggleGroup = (groupKey: string) => {
48	    setCollapsedGroups(prev => {
49	      const next = new Set(prev)
50	      if (next.has(groupKey)) next.delete(groupKey); else next.add(groupKey)
51	      return next
52	    })
53	  }
54	
