3	import DetailPanel from '../DetailPanel'
4	import Toolbar from '../Toolbar'
5	import TruncatedText from '../TruncatedText'
6	import DriveFolderPickerModal from './components/DriveFolderPickerModal'
7	import DriveThumbnailPanel from './components/ThumbnailPanel'
8	import GroupNode from './components/GroupNode'
9	import FileList from './components/FileList'
10	import ResizableLeftPanel from './components/ResizableLeftPanel'
11	import UploadModal from './components/UploadModal'
12	import { useFileTree } from './hooks/useFileTree'
13	import { useDriveAssignments } from './hooks/useDriveAssignments'
14	import { useInclusion } from './hooks/useInclusion'
15	import { useSelection } from './hooks/useSelection'
16	import { useUploadFlow } from './hooks/useUploadFlow'
17	import { usePreview } from './hooks/usePreview'
18	import { pruneSelectionForAssignment } from './pruneSelection'
19	import { DriveAssignment, SelectionItem } from './types'
20	import { ellipsisPath } from '../../utils'
21	import styles from './index.module.css'
22	
23	export default function DriveUploadMode() {
24	  const { root, tree, loading, error, pickRoot } = useFileTree()
25	  const isEmpty = tree !== null && tree.files.length === 0 && tree.subgroups.length === 0
26	
27	  const preview = usePreview()
28	
29	  // Groups start expanded; presence in this set (keyed by the group's full
30	  // path, e.g. "invoices/2026") means collapsed.
31	  const [collapsedGroups, setCollapsedGroups] = useState<Set<string>>(new Set())
32	  const toggleGroup = (groupKey: string) => {
33	    setCollapsedGroups(prev => {
34	      const next = new Set(prev)
35	      if (next.has(groupKey)) next.delete(groupKey); else next.add(groupKey)
36	      return next
37	    })
38	  }
39	
40	  const inclusion = useInclusion(tree)
41	  const selection = useSelection(tree)
42	  const assignments = useDriveAssignments()
43	  // One or more targets for the currently open folder picker: a single-item
44	  // array for a per-row badge click, or the pruned multi-selection for the
45	  // toolbar batch action below — either way, the picked folder applies to
46	  // every target here.
47	  const [pickerTargets, setPickerTargets] = useState<SelectionItem[] | null>(null)
48	  const handlePicked = (folder: DriveAssignment) => {
49	    for (const target of pickerTargets ?? []) {
50	      if (target.type === 'group') assignments.setGroupAssignment(target.key, folder)
51	      else assignments.setFileOverride(target.path, folder)
52	    }
53	    setPickerTargets(null)
54	  }
55	  const handleBatchAssign = () => {
56	    if (!tree) return
57	    setPickerTargets(pruneSelectionForAssignment(tree, selection.items))
58	  }
59	
60	  const uploadFlow = useUploadFlow(tree, inclusion, assignments)
61	  const handlePickRoot = async () => {
62	    if (await pickRoot()) uploadFlow.reset()
63	  }
64	
65	  return (
66	    <Box className={styles.root}>
67	      <Toolbar>
68	        <Button size="xs" variant="default" onClick={handlePickRoot}>
69	          {root ? ellipsisPath(root) : 'Choose root folder…'}
70	        </Button>
71	        <Box className={styles.toolbarSpacer} />
72	        <Button size="xs" variant="default" disabled={uploadFlow.started || !tree} onClick={inclusion.selectAll}>
73	          Select All
74	        </Button>
75	        <Button size="xs" variant="default" disabled={uploadFlow.started || !tree} onClick={inclusion.selectNone}>
76	          Select None
77	        </Button>
78	        <Button size="xs" variant="default" disabled={uploadFlow.started || !tree || selection.size === 0} onClick={handleBatchAssign}>
79	          Assign Drive folder…
80	        </Button>
81	        <Tooltip
82	          label={tree ? 'Every selected file needs a Drive folder before uploading' : 'Choose a root folder first'}
83	          disabled={uploadFlow.started || uploadFlow.readyToUpload}
84	        >
85	          <span>
86	            <Button size="xs" disabled={uploadFlow.started || !uploadFlow.readyToUpload} onClick={uploadFlow.startUpload}>
87	              Upload All
88	            </Button>
89	          </span>
90	        </Tooltip>
91	      </Toolbar>
92	
93	      <Box className={styles.body}>
94	        <ResizableLeftPanel
95	          left={
96	            <>
97	              <DriveFolderPickerModal
98	                opened={pickerTargets !== null}
99	                onClose={() => setPickerTargets(null)}
100	                onSelect={handlePicked}
101	              />
102	              {tree && (
103	                <UploadModal
104	                  opened={uploadFlow.uploadModalOpen}
105	                  tree={tree}
106	                  onClose={uploadFlow.closeUploadModal}
107	                />
108	              )}
109	
110	              {loading && <Loader size="sm" />}
111	              {error && <Text size="sm" c="red">{error}</Text>}
112	              {!loading && !error && isEmpty && (
113	                <Text size="sm" c="dimmed">No files found under this folder.</Text>
114	              )}
115	
116	              {tree && (
117	                <Stack gap="md">
118	                  {tree.subgroups.map(group => (
119	                    <GroupNode
120	                      key={group.name}
121	                      group={group}
122	                      groupKey={group.name}
123	                      collapsedGroups={collapsedGroups}
124	                      onToggle={toggleGroup}
125	                      assignments={assignments}
126	                      inheritedAssignment={null}
127	                      inclusion={inclusion}
128	                      selection={selection}
129	                      locked={uploadFlow.started}
130	                      onPick={target => setPickerTargets([target])}
131	                      onPreviewFile={preview.setFile}
132	                    />
133	                  ))}
134	                  <FileList
135	                    files={tree.files}
136	                    assignments={assignments}
137	                    inheritedAssignment={null}
138	                    inclusion={inclusion}
139	                    selection={selection}
140	                    locked={uploadFlow.started}
141	                    onPick={target => setPickerTargets([target])}
142	                    onPreviewFile={preview.setFile}
143	                  />
144	                </Stack>
145	              )}
146	            </>
147	          }
148	        >
149	          <DriveThumbnailPanel
150	            pdfPath={preview.file?.path ?? null}
151	            pageCount={preview.file?.pageCount ?? 0}
152	            selectedPage={preview.page}
153	            onSelectPage={preview.setPage}
154	          />
155	
156	          <Box className={styles.detailColumn}>
157	            {preview.file && (
158	              <TruncatedText label={preview.file.name} size="sm" fw={600} className={styles.detailHeading}>
159	                {preview.file.name}
160	              </TruncatedText>
161	            )}
162	            {preview.file
163	              ? <DetailPanel pdfPath={preview.file.path} pageNum={preview.page} pageCount={preview.file.pageCount} />
164	              : <Box className={styles.emptyDetail} />}
165	          </Box>
166	        </ResizableLeftPanel>
167	      </Box>
168	    </Box>
169	  )
170	}

